// Clase concreta orientada a la certificación de documentos tributarios electrónicos
public class CertificadorFELOnline extends AbstractIntegracion implements Consultable, Documentable {
    private String nitFranquicia;
    private int cantidadDocumentosCertificadosHoy;

    public CertificadorFELOnline(String id, String nombre, String estado, double latencia, String nitFranquicia) {
        super(id, nombre, estado, latencia);
        this.nitFranquicia = nitFranquicia;
        this.cantidadDocumentosCertificadosHoy = 150;
    }

    @Override
    public String mostrarDetalles() {
        return "Certificador FEL [" + identificador + "] - NIT: " + nitFranquicia;
    }

    @Override
    public String consultarEstado() { 
        return estadoConexion; 
    }

    @Override
    public double cotizar(String detalleServicio) { 
        return 15.0; 
    }

    @Override
    public double cotizarMonto(double monto) { 
        return 5.0; // Tarifa fija por DTE fiscal autorizado
    }

    @Override
    public String generarDocumento() { 
        cantidadDocumentosCertificadosHoy++;
        return "DTE (Documento Tributario Electrónico) Autorizado y Firmado Electrónicamente."; 
    }
}
